import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeEncryptedPayload:
    key_id: str
    algorithm: str
    encrypted_data_key_b64: str
    nonce_b64: str
    ciphertext_b64: str
    associated_data_b64: Optional[str] = None

    def to_json(self) -> str:
        return json.dumps(
            {
                "key_id": self.key_id,
                "algorithm": self.algorithm,
                "encrypted_data_key_b64": self.encrypted_data_key_b64,
                "nonce_b64": self.nonce_b64,
                "ciphertext_b64": self.ciphertext_b64,
                "associated_data_b64": self.associated_data_b64,
            },
            separators=(",", ":"),
        )

    @staticmethod
    def from_json(data: str) -> "EnvelopeEncryptedPayload":
        obj = json.loads(data)
        return EnvelopeEncryptedPayload(
            key_id=obj["key_id"],
            algorithm=obj["algorithm"],
            encrypted_data_key_b64=obj["encrypted_data_key_b64"],
            nonce_b64=obj["nonce_b64"],
            ciphertext_b64=obj["ciphertext_b64"],
            associated_data_b64=obj.get("associated_data_b64"),
        )


class AwsKmsEnvelopeEncryption:
    """
    Envelope encryption using AWS KMS as the managed key service.

    Requires:
      - AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY / AWS_SESSION_TOKEN (if applicable)
      - AWS_REGION
      - A valid AWS KMS key id or ARN
    """

    def __init__(self, key_id: str, region_name: Optional[str] = None):
        self.key_id = key_id
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
        if not self.region_name:
            raise ValueError("AWS region must be provided via region_name, AWS_REGION, or AWS_DEFAULT_REGION")
        self.kms = boto3.client("kms", region_name=self.region_name)

    @staticmethod
    def _b64e(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")

    @staticmethod
    def _b64d(data_b64: str) -> bytes:
        return base64.b64decode(data_b64.encode("ascii"))

    def encrypt(self, plaintext: bytes, associated_data: Optional[bytes] = None) -> str:
        try:
            kms_resp = self.kms.generate_data_key(KeyId=self.key_id, KeySpec="AES_256")
            plaintext_data_key = kms_resp["Plaintext"]
            encrypted_data_key = kms_resp["CiphertextBlob"]

            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            aesgcm = AESGCM(plaintext_data_key)
            nonce = os.urandom(12)
            aad = associated_data if associated_data is not None else None
            ciphertext = aesgcm.encrypt(nonce, plaintext, aad)

            payload = EnvelopeEncryptedPayload(
                key_id=self.key_id,
                algorithm="AES-256-GCM+AWS-KMS",
                encrypted_data_key_b64=self._b64e(encrypted_data_key),
                nonce_b64=self._b64e(nonce),
                ciphertext_b64=self._b64e(ciphertext),
                associated_data_b64=self._b64e(associated_data) if associated_data is not None else None,
            )
            return payload.to_json()
        except (ClientError, BotoCoreError, ValueError, ImportError) as exc:
            raise RuntimeError(f"Envelope encryption failed: {exc}") from exc

    def decrypt(self, envelope_json: str) -> bytes:
        try:
            payload = EnvelopeEncryptedPayload.from_json(envelope_json)

            encrypted_data_key = self._b64d(payload.encrypted_data_key_b64)
            nonce = self._b64d(payload.nonce_b64)
            ciphertext = self._b64d(payload.ciphertext_b64)
            associated_data = self._b64d(payload.associated_data_b64) if payload.associated_data_b64 is not None else None

            kms_resp = self.kms.decrypt(CiphertextBlob=encrypted_data_key)
            plaintext_data_key = kms_resp["Plaintext"]

            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            aesgcm = AESGCM(plaintext_data_key)
            return aesgcm.decrypt(nonce, ciphertext, associated_data)
        except (ClientError, BotoCoreError, ValueError, ImportError, KeyError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"Envelope decryption failed: {exc}") from exc


def encrypt_envelope(plaintext: bytes, key_id: Optional[str] = None, associated_data: Optional[bytes] = None) -> str:
    key_id = key_id or os.getenv("AWS_KMS_KEY_ID")
    if not key_id:
        raise ValueError("KMS key id must be provided via key_id or AWS_KMS_KEY_ID")
    return AwsKmsEnvelopeEncryption(key_id=key_id).encrypt(plaintext, associated_data=associated_data)


def decrypt_envelope(envelope_json: str) -> bytes:
    key_id = os.getenv("AWS_KMS_KEY_ID", "")
    return AwsKmsEnvelopeEncryption(key_id=key_id or "unused").decrypt(envelope_json)
